mapper.select:
SELECT COUNT(*)
  FROM CHATBOT_LINK_CLICK
 WHERE clicked_at >= #{from}
   AND clicked_at <  #{to}

SELECT url            AS url,
       COUNT(*)       AS clickCount
  FROM CHATBOT_LINK_CLICK
 WHERE clicked_at >= #{from}
   AND clicked_at <  #{to}
 GROUP BY url
 ORDER BY clickCount DESC, url ASC
 LIMIT #{limit}

SELECT click_id, message_id, conversation_id, user_idx, anon_session_id,
       url, label, ip_address, clicked_at
  FROM CHATBOT_LINK_CLICK
 WHERE user_idx = #{userIdx}
 ORDER BY clicked_at DESC
 LIMIT #{limit}

SELECT click_id, message_id, conversation_id, user_idx, anon_session_id,
       url, label, ip_address, clicked_at
  FROM CHATBOT_LINK_CLICK
 WHERE ip_address = #{ip}
 ORDER BY clicked_at DESC
 LIMIT #{limit}

SELECT click_id, message_id, conversation_id, user_idx, anon_session_id,
       url, label, ip_address, clicked_at
  FROM CHATBOT_LINK_CLICK
 WHERE user_idx = #{userIdx}
   AND ip_address = #{ip}
 ORDER BY clicked_at DESC
 LIMIT #{limit}

SELECT click_id, message_id, conversation_id, user_idx, anon_session_id,
       url, label, ip_address, clicked_at
  FROM CHATBOT_LINK_CLICK
 WHERE user_idx = #{userIdx}
    OR ip_address = #{ip}
 ORDER BY clicked_at DESC
 LIMIT #{limit}
